@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-pagination {
    --_nz-pagination-size: var(--nz-size-control-md);

    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--nz-space-2) var(--nz-space-4);
  }

  .nz-pagination[data-size='sm'] {
    --_nz-pagination-size: var(--nz-size-control-sm);
  }

  .nz-pagination-summary {
    margin: 0;
    color: var(--nz-pagination-summary-fg, var(--nz-text-secondary));
    font: var(--nz-font-body-m);
    font-variant-numeric: tabular-nums;
  }

  .nz-pagination-list {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--nz-pagination-gap, var(--nz-space-1));
    margin: 0;
    margin-inline-start: auto;
    padding: 0;
    list-style: none;
  }

  .nz-pagination-page,
  .nz-pagination-step,
  .nz-pagination-ellipsis {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    min-inline-size: var(--_nz-pagination-size);
    block-size: var(--_nz-pagination-size);
    padding-inline: var(--nz-space-1);
    border: var(--nz-border-width-default) solid transparent;
    border-radius: var(--nz-pagination-radius, var(--nz-radius-sm));
    color: var(--nz-pagination-fg, var(--nz-text-secondary));
    font: var(--nz-font-label-m);
    letter-spacing: var(--nz-tracking-label-m);
    font-variant-numeric: tabular-nums;
    text-decoration: none;
    transition:
      background-color var(--nz-duration-fast) var(--nz-easing-standard),
      color var(--nz-duration-fast) var(--nz-easing-standard);
  }

  .nz-pagination-step {
    border-color: var(--nz-pagination-step-border, var(--nz-border-default));
    color: var(--nz-pagination-step-fg, var(--nz-icon-secondary));
  }

  /* button mode (`onPageChange`): the same squares, without the browser's button face */
  .nz-pagination-page:is(button),
  .nz-pagination-step:is(button) {
    margin: 0;
    background: none;
    cursor: pointer;
  }

  @media (hover: hover) {
    .nz-pagination-page:not([aria-current='page']):hover,
    .nz-pagination-step:not([data-disabled]):hover {
      background: var(--nz-pagination-bg-hover, var(--nz-bg-hover));
      color: var(--nz-text-primary);
    }
  }

  .nz-pagination-page[aria-current='page'] {
    background: var(--nz-pagination-bg-current, var(--nz-bg-inverse));
    color: var(--nz-pagination-fg-current, var(--nz-text-inverse));
  }

  .nz-pagination-step[data-disabled] {
    color: var(--nz-text-disabled);
    cursor: not-allowed;
  }

  .nz-pagination-icon {
    display: inline-flex;
    flex: none;
    inline-size: var(--nz-size-icon-sm);
    block-size: var(--nz-size-icon-sm);
    /* internal glyphs are 1em: size them to the slot */
    font-size: var(--nz-size-icon-sm);

    & > svg {
      inline-size: 100%;
      block-size: 100%;
    }
  }

  /* the chevron points right; previous turns it (and the RTL mirror flips both back) */
  .nz-pagination-previous > .nz-pagination-icon > .nz-glyph {
    rotate: 180deg;
  }

  @media (forced-colors: active) {
    /* nz.base's generated highlight loses to the background above (a later layer, §8.5), so repeat
       it: without it the current page is painted as Canvas and only aria-current is left */
    .nz-pagination-page[aria-current='page'] {
      background: Highlight;
      color: HighlightText;
      forced-color-adjust: none;
    }

    .nz-pagination-step[data-disabled] {
      color: GrayText;
    }
  }

  /* Optical centring (M85, as Button's label): trimmed to cap height and baseline, padded back to
     one line, so the box keeps its height and the letters sit in its middle. */
  @supports (text-box: trim-both cap alphabetic) {
    .nz-pagination-summary,
    .nz-pagination-page-text {
      padding-block: calc((1lh - 1cap) / 2);
      text-box: trim-both cap alphabetic;
    }
  }
}
